from dataclasses import dataclass, field
from datetime import datetime
from typing import Optional

# DECISION PENDING (product): expired promotion handling.
# Current choice: don't reject the order, don't apply the discount, and report
# the expiry so the UI can ask the customer to confirm the full price.
EXPIRED_POLICY = "ignore"


@dataclass
class Promotion:
    code: str
    percent_off: float
    expires_at: datetime


@dataclass
class CheckoutResult:
    total: float
    promotion_applied: bool = False
    warnings: list = field(default_factory=list)


def checkout(subtotal: float, promotion: Optional[Promotion], now: datetime) -> CheckoutResult:
    if promotion is None:
        return CheckoutResult(total=subtotal)
    if now >= promotion.expires_at:
        return CheckoutResult(total=subtotal, warnings=[f"promotion {promotion.code} expired"])
    return CheckoutResult(total=round(subtotal * (1 - promotion.percent_off / 100), 2), promotion_applied=True)
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
from checkout import Promotion, checkout

NOW = datetime(2026, 1, 1)


def promo(delta):
    return Promotion("SAVE10", 10, NOW + delta)


def test_valid_promotion_applies():
    r = checkout(100, promo(timedelta(days=1)), NOW)
    assert r.total == 90 and r.promotion_applied and not r.warnings


def test_expired_promotion_is_ignored_with_warning():
    r = checkout(100, promo(-timedelta(days=1)), NOW)
    assert r.total == 100 and not r.promotion_applied
    assert r.warnings == ["promotion SAVE10 expired"]


def test_expiry_boundary_counts_as_expired():
    assert not checkout(100, promo(timedelta(0)), NOW).promotion_applied


def test_no_promotion():
    assert checkout(100, None, NOW).total == 100
E
